/**
 * Two years of synthetic journey data for one demo business (BUILD §17.2, AC-11.2.1), generated by
 * `@foundmill/journey` and persisted as the real tables the Ribbon, Customer Updates and department cards read:
 * customers as CRM entities (+ roles), visitors, campaigns, touches, conversions, journeys (attribution weights,
 * xC series, agents on the team sheet, commentary lines), milestones (trophies, launches, decisions, releases),
 * agent_sessions per department per day (what `journey_daily_mv` rolls into agent hours and spend) and
 * channel_metrics per channel per day. Every number is synthetic; `meta.label` and the `label` fields say so.
 */
import {
  buildJourney, buildMarkovModel, conversionPathsFromTouches, generateSyntheticJourneyData, percentile75, selectXcModel, syntheticConversionGroups, trainXcModel,
  xcSamplesFromPaths, type Conversion as JourneyConversion, type JourneyAgentInput, type MarkovModel, type SyntheticCustomer, type SyntheticJourneyData,
  type Touch as JourneyTouch, type XcModel,
} from "@foundmill/journey";
import { CHANNEL_META, type Archetype, type ChannelKey, type ConversionKind, type Visibility } from "@foundmill/shared";
import {
  agentSessions, campaigns, channelMetrics, conversions, entities, entityRoles, events, journeys, milestones, outbox, touches, visitors,
  type Channel, type Department, type NewAgentSession, type NewCampaign, type NewChannelMetric, type NewConversion, type NewEntity, type NewEntityRole, type NewEvent,
  type NewJourney, type NewMilestone, type NewOutboxRow, type NewTouch, type NewVisitor,
} from "../schema";
import { addDays, atHour, bulkInsert, DAY_MS, dayKey, HOUR_MS, mention, money, monthKey, type SeedCtx } from "./context";
import { agentsInDepartment, type SeededAgent, type SquadResult } from "./squad";

export interface JourneySeedOptions {
  businessId: string;
  slug: string;
  archetype: Archetype;
  currency: string;
  siteHost: string;
  squad: SquadResult;
  departments: Department[];
  channels: Channel[];
  /** Where payments come from: Shopify orders or Stripe subscriptions. */
  customerSource: "shopify" | "stripe";
  /** Visibility of customer entities and milestones (public for LIVE businesses, BUILD §7.3). */
  visibility: Visibility;
  /** Days back from today the business "opened" (defaults to the whole window). */
}

export interface RecentSession {
  id: string;
  agentId: string;
  modelKey: "opus" | "sonnet" | "haiku";
  tokensIn: number;
  tokensOut: number;
  costMinor: number;
  occurredAt: Date;
}

export interface LatestPayment {
  conversion: JourneyConversion;
  customer: SyntheticCustomer;
  journeyId: string | null;
  eventId: string | null;
}

export interface JourneySeedResult {
  data: SyntheticJourneyData;
  customersByEntityId: Map<string, SyntheticCustomer>;
  latestPayments: LatestPayment[];
  /** Payment revenue per YYYY-MM (minor units). */
  revenueByMonth: Map<string, number>;
  /** Agent model + sandbox cost per YYYY-MM (minor units). */
  agentSpendByMonth: Map<string, number>;
  /** Channel spend per YYYY-MM (minor units). */
  adSpendByMonth: Map<string, number>;
  paidCustomers: number;
  signups: number;
  activations: number;
  mrrMinorNow: number;
  revenueLast30dMinor: number;
  spendLast30dMinor: number;
  counts: { entities: number; visitors: number; touches: number; conversions: number; journeys: number; milestones: number; sessions: number; channelMetrics: number; campaigns: number; events: number };
  recentSessions: RecentSession[];
  campaignIdsByChannel: Map<ChannelKey, string[]>;
  trophyMilestoneIds: string[];
  channelById: Map<string, Channel>;
}

const COMMENTARY_LABELS: Record<string, (label: string, src: Record<string, unknown>) => string> = {
  visit: (label, src) => `Visited ${pathOf(src.landingUrl)} from ${label}.`,
  ad_click: (label) => `Clicked a ${label} ad.`,
  email_open: (label, src) => `${src.label ?? "Opened an email"} (${label}).`,
  email_click: (label, src) => `${src.label ?? "Clicked an email"} (${label}).`,
  email_reply: (label, src) => `${src.label ?? "Replied"} (${label}).`,
  code_redeemed: (label, src) => `Redeemed code ${String(src.code ?? "")} (${label}).`,
  qr_scan: (label) => `Scanned the QR code (${label}).`,
  call: (label, src) => `${src.label ?? "Called the tracking number"} (${label}).`,
  meeting: (label, src) => `${src.label ?? "Meeting booked"} (${label}).`,
  form_submit: (label, src) => `${src.label ?? "Submitted a form"} (${label}).`,
};

function pathOf(url: unknown): string {
  if (typeof url !== "string" || !url) return "the site";
  try {
    const u = new URL(url);
    return u.pathname === "/" ? "the home page" : u.pathname;
  } catch {
    return "the site";
  }
}

const channelLabel = (key: ChannelKey | null): string => (key ? CHANNEL_META[key].label : "Direct");

function commentaryLines(kind: ConversionKind, amountMinor: number, currency: string, customer: SyntheticCustomer, path: JourneyTouch[]): Record<string, unknown>[] {
  const who = mention(customer.entityId, customer.displayName);
  const lines: Record<string, unknown>[] = [];
  const first = path[0];
  lines.push({
    text: `First touch (synthetic demo data): ${who} first appeared via ${channelLabel(first?.channelKey ?? null)}.`,
    touchId: null,
    touchIndex: null,
    tone: "build_up",
    highlight: false,
  });
  path.forEach((t, i) => {
    const render = COMMENTARY_LABELS[t.kind] ?? COMMENTARY_LABELS.visit!;
    lines.push({
      text: render(channelLabel(t.channelKey), t.source as unknown as Record<string, unknown>),
      touchId: t.id,
      touchIndex: i,
      tone: i === path.length - 1 ? "chance" : "build_up",
      highlight: false,
    });
  });
  const win = kind === "payment" ? `paid ${money(amountMinor, currency)}` : kind === "activation" ? "reached activation" : "signed up";
  lines.push({ text: `Win moment: ${who} ${win}.`, touchId: null, touchIndex: null, tone: "goal", highlight: true });
  return lines;
}

const slugName = (s: string): string => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");

export async function seedJourney(ctx: SeedCtx, opts: JourneySeedOptions): Promise<JourneySeedResult> {
  const { db } = ctx;
  const rng = ctx.rng.fork(`journey:${opts.slug}`);
  const businessId = opts.businessId;
  const log = (m: string) => ctx.log(`[${opts.slug}] ${m}`);

  const data = generateSyntheticJourneyData({
    seed: `${ctx.seed}:${opts.slug}`,
    startDate: ctx.startKey,
    days: ctx.days,
    departments: opts.departments.map((d) => ({ id: d.id, name: d.name, moduleKeys: d.moduleKeys as ("product" | "development" | "distribution" | "finance" | "team" | "legal")[] })),
    archetype: opts.archetype,
    currency: opts.currency,
    businessId,
    siteHost: opts.siteHost,
    volumeScale: ctx.volumeScale,
    today: ctx.todayKey,
  });
  log(`generated ${data.customers.length} customers, ${data.touches.length} touches, ${data.conversions.length} conversions, ${data.daily.length} daily rows`);

  const channelByKey = new Map<ChannelKey, Channel>(opts.channels.map((c) => [c.channelKey, c]));
  const channelById = new Map<string, Channel>(opts.channels.map((c) => [c.id, c]));

  // Synthetic agents in touch sources → the real channel agents of the squad.
  const realByChannel = new Map<ChannelKey, SeededAgent>();
  for (const a of opts.squad.agents) if (a.template.channelKey) realByChannel.set(a.template.channelKey, a);
  const agentRemap = new Map<string, string | null>();
  for (const sa of data.agents) {
    const hit = (sa.channelKeys ?? []).map((k) => realByChannel.get(k)).find((a): a is SeededAgent => Boolean(a));
    agentRemap.set(sa.agentId, hit?.agent.id ?? null);
  }
  for (const t of data.touches) {
    if (t.source.agentId) t.source.agentId = agentRemap.get(t.source.agentId) ?? null;
  }
  const journeyAgents: JourneyAgentInput[] = [...realByChannel.entries()].map(([channelKey, a]) => ({
    agentId: a.agent.id,
    name: a.agent.name,
    role: a.agent.role,
    departmentId: a.agent.departmentIds[0] ?? null,
    channelKeys: [channelKey],
  }));

  // --- customers → entities + roles ----------------------------------------------------------------------------------
  const customersByEntityId = new Map(data.customers.map((c) => [c.entityId, c]));
  const distributionDept = opts.departments.find((d) => d.moduleKeys.includes("distribution")) ?? null;
  const entityRows: NewEntity[] = [];
  const roleRows: NewEntityRole[] = [];
  const domains = ["example", "test", "invalid"];
  for (const c of data.customers) {
    const handle = slugName(c.displayName) || "customer";
    const identifiers = c.kind === "organisation" ? { domain: `${handle}.${rng.pick(domains)}`, ...(opts.customerSource === "stripe" ? { stripe_id: `cus_${c.entityId.replace(/-/g, "").slice(0, 14)}` } : {}) } : { email: `${handle}@${rng.pick(["mail", "inbox", "post"])}.${rng.pick(domains)}` };
    entityRows.push({
      id: c.entityId,
      businessId,
      kind: c.kind,
      displayName: c.displayName,
      aliases: c.kind === "person" ? [c.displayName.split(" ")[0]!] : [],
      identifiers,
      lawfulBasis: "contract",
      source: opts.customerSource,
      visibility: opts.visibility,
      createdAt: new Date(c.signupAt),
    });
    const stage = c.paidAt ? (c.churnedAt && Date.parse(c.churnedAt) <= ctx.today.getTime() ? "churned" : "customer") : c.activatedAt ? "activated" : "signed_up";
    roleRows.push({
      id: rng.uuid(),
      businessId,
      entityId: c.entityId,
      role: "customer",
      stage,
      ownerRef: distributionDept ? { kind: "department", id: distributionDept.id } : null,
      startedAt: new Date(c.signupAt),
      endedAt: stage === "churned" && c.churnedAt ? new Date(c.churnedAt) : null,
    });
  }
  await bulkInsert(db, entities, entityRows);
  await bulkInsert(db, entityRoles, roleRows);
  log(`inserted ${entityRows.length} customer entities`);

  // --- visitors ------------------------------------------------------------------------------------------------------
  const visitorRows: NewVisitor[] = data.visitors.map((v) => ({
    id: v.id,
    businessId,
    anonId: v.anonId,
    entityId: v.entityId,
    firstSeen: new Date(v.firstSeen),
    lastSeen: new Date(v.lastSeen),
    consentState: v.consentState,
  }));
  await bulkInsert(db, visitors, visitorRows);

  // --- campaigns -----------------------------------------------------------------------------------------------------
  const campaignRows: NewCampaign[] = [];
  const campaignIdsByChannel = new Map<ChannelKey, string[]>();
  const launchDay = addDays(ctx.startDate, Math.round(ctx.days * 0.06));
  for (const c of data.campaigns) {
    const channel = channelByKey.get(c.channelKey);
    if (!channel) continue;
    const enabled = channel.enabled;
    const status = enabled ? rng.weighted(["live", "paused", "scheduled"] as const, [0.7, 0.2, 0.1]) : rng.weighted(["ended", "draft"] as const, [0.7, 0.3]);
    const startsAt = addDays(launchDay, rng.int(0, Math.max(1, ctx.days - 60)));
    campaignRows.push({
      id: c.id,
      businessId,
      channelId: channel.id,
      name: c.name,
      goal: `${CHANNEL_META[c.channelKey].coreMetric} (Synthetic)`,
      status,
      budgetMinor: rng.int(8, 60) * 5_000,
      currency: opts.currency,
      startsAt,
      endsAt: status === "ended" ? addDays(startsAt, rng.int(20, 90)) : status === "scheduled" ? null : null,
      config: { code: c.code, vanityPath: c.vanityPath, trackingNumber: c.trackingNumber, label: "Synthetic" },
    });
    campaignIdsByChannel.set(c.channelKey, [...(campaignIdsByChannel.get(c.channelKey) ?? []), c.id]);
  }
  await bulkInsert(db, campaigns, campaignRows);
  const knownCampaignIds = new Set(campaignRows.map((c) => c.id as string));

  // --- touches -------------------------------------------------------------------------------------------------------
  const touchRows: NewTouch[] = data.touches.map((t) => ({
    id: t.id,
    businessId,
    visitorId: t.visitorId,
    entityId: t.entityId,
    occurredAt: new Date(t.occurredAt),
    channelKey: t.channelKey,
    campaignId: t.campaignId && knownCampaignIds.has(t.campaignId) ? t.campaignId : null,
    source: t.source as unknown as Record<string, unknown>,
    kind: t.kind,
  }));
  await bulkInsert(db, touches, touchRows, 300);
  log(`inserted ${touchRows.length} touches`);

  // --- events for the most recent payments (webhook-shaped, so inbox items can cite them) ---------------------------
  const payments = data.conversions.filter((c) => c.kind === "payment");
  const latest = payments.slice(-5);
  const eventRows: NewEvent[] = [];
  const outboxRows: NewOutboxRow[] = [];
  const eventIdByConversion = new Map<string, string>();
  latest.forEach((c, i) => {
    const id = rng.uuid();
    eventIdByConversion.set(c.id, id);
    const customer = customersByEntityId.get(c.entityId ?? "");
    eventRows.push({
      id,
      businessId,
      type: "payment.received",
      occurredAt: new Date(c.occurredAt),
      actor: { kind: "webhook", id: opts.customerSource },
      entityIds: c.entityId ? [c.entityId] : [],
      payload: {
        provider: opts.customerSource,
        amountMinor: c.amountMinor,
        currency: c.currency,
        conversionId: c.id,
        customerName: customer?.displayName ?? null,
        ...(opts.customerSource === "shopify" ? { orderId: `#${10_000 + payments.length - latest.length + i}` } : { subscriptionId: `sub_${c.id.replace(/-/g, "").slice(0, 14)}` }),
        label: "Synthetic",
      },
      narrated: i < latest.length - 2,
      idempotencyKey: `seed:${opts.slug}:payment:${c.id}`,
    });
    outboxRows.push({ businessId, eventId: id, publishedAt: new Date(c.occurredAt), attempts: 1 });
  });
  await bulkInsert(db, events, eventRows);
  await bulkInsert(db, outbox, outboxRows);

  // --- conversions ---------------------------------------------------------------------------------------------------
  const conversionRows: NewConversion[] = data.conversions.map((c) => ({
    id: c.id,
    businessId,
    entityId: c.entityId,
    kind: c.kind,
    amountMinor: c.amountMinor,
    currency: c.currency,
    occurredAt: new Date(c.occurredAt),
    sourceEventId: eventIdByConversion.get(c.id) ?? null,
  }));
  await bulkInsert(db, conversions, conversionRows);

  // --- journeys (attribution, xC, team sheet, commentary) -----------------------------------------------------------
  const groups = syntheticConversionGroups(data);
  const markov: MarkovModel = buildMarkovModel(conversionPathsFromTouches(groups));
  const trained: XcModel = trainXcModel(xcSamplesFromPaths(groups), { archetype: opts.archetype, epochs: 60, conversionCount: payments.length });
  const byVisitor = new Map<string, JourneyTouch[]>();
  const byEntity = new Map<string, JourneyTouch[]>();
  for (const t of data.touches) {
    if (t.visitorId) byVisitor.set(t.visitorId, [...(byVisitor.get(t.visitorId) ?? []), t]);
    if (t.entityId) byEntity.set(t.entityId, [...(byEntity.get(t.entityId) ?? []), t]);
  }
  const cpaByChannelMinor = Object.fromEntries(opts.channels.map((c) => [c.channelKey, c.channelKey === "paid_ads" ? 2_600 : 1_100])) as Partial<Record<ChannelKey, number>>;
  const journeyRows: NewJourney[] = [];
  const journeyIdByConversion = new Map<string, string>();
  const kindCount: Record<ConversionKind, number> = { signup: 0, activation: 0, payment: 0 };
  const paymentValues: number[] = [];
  const recentCutoff = ctx.today.getTime() - 45 * DAY_MS;
  let seen = 0;
  for (const c of data.conversions) {
    seen += 1;
    kindCount[c.kind] += 1;
    const customer = c.entityId ? customersByEntityId.get(c.entityId) : undefined;
    const wanted = c.kind === "payment" || kindCount[c.kind] <= 60 || Date.parse(c.occurredAt) >= recentCutoff;
    if (!customer || !wanted) {
      if (c.kind === "payment") paymentValues.push(c.amountMinor);
      continue;
    }
    const pathTouches = [...(byVisitor.get(customer.visitorId) ?? []), ...(byEntity.get(customer.entityId) ?? []).filter((t) => t.visitorId !== customer.visitorId)];
    const counts = {
      conversions: seen,
      nthOfKind: kindCount[c.kind],
      valuePercentile75Minor: percentile75(paymentValues),
      flaggedHighValue: customer.enterprise,
    };
    const journey = buildJourney({
      conversion: c,
      touches: pathTouches,
      agents: journeyAgents,
      consent: customer.consent,
      counts,
      archetype: opts.archetype,
      markov,
      xcModel: selectXcModel({ archetype: opts.archetype, conversionCount: kindCount.payment, trained }),
      costs: { cpaByChannelMinor },
      visitorIds: [customer.visitorId],
      businessId,
    });
    const orderedPath = journey.touchIds.map((id) => pathTouches.find((t) => t.id === id)).filter((t): t is JourneyTouch => Boolean(t));
    const id = rng.uuid();
    journeyIdByConversion.set(c.id, id);
    const at = Date.parse(c.occurredAt);
    journeyRows.push({
      id,
      businessId,
      conversionId: c.id,
      touchIds: journey.touchIds,
      weights: journey.weights,
      xcSeries: journey.xcSeries,
      commentary: commentaryLines(c.kind, c.amountMinor, c.currency, customer, orderedPath),
      agents: journey.agents,
      matchdayLevel: journey.matchdayLevel,
      viewedAt: at < ctx.today.getTime() - 10 * DAY_MS ? new Date(at + 6 * HOUR_MS + rng.int(0, 40) * HOUR_MS) : null,
      createdAt: new Date(at + 60_000),
    });
    if (c.kind === "payment") paymentValues.push(c.amountMinor);
  }
  await bulkInsert(db, journeys, journeyRows, 200);
  log(`built ${journeyRows.length} journeys`);

  // --- milestones ----------------------------------------------------------------------------------------------------
  const trophyMilestoneIds: string[] = [];
  const milestoneRows: NewMilestone[] = data.milestones.map((m) => {
    const id = m.id ?? rng.uuid();
    if (m.trophyKey) trophyMilestoneIds.push(id);
    return {
      id,
      businessId,
      kind: m.kind,
      label: m.label,
      achievedAt: new Date(m.achievedAt),
      ref: { ...(m.ref ?? {}), trophyKey: m.trophyKey ?? null, label: "Synthetic" },
      visibility: opts.visibility,
    };
  });
  await bulkInsert(db, milestones, milestoneRows);

  // --- agent sessions from the per-department daily rows ------------------------------------------------------------
  const sessionRows: NewAgentSession[] = [];
  const recentSessions: RecentSession[] = [];
  const agentSpendByMonth = new Map<string, number>();
  const membersByDept = new Map<string, SeededAgent[]>(opts.departments.map((d) => [d.id, agentsInDepartment(opts.squad, d.id)]));
  const startMs = ctx.startDate.getTime();
  for (const row of data.daily) {
    if (!row.departmentId || row.agentHours <= 0) continue;
    const members = membersByDept.get(row.departmentId) ?? [];
    if (members.length === 0) continue;
    const day = new Date(`${row.day}T00:00:00.000Z`);
    const dayIndex = Math.round((day.getTime() - startMs) / DAY_MS);
    const n = Math.min(members.length, Math.max(1, Math.ceil(row.agentHours / 5)), 3);
    const hoursEach = row.agentHours / n;
    const spendEach = Math.round(row.spendMinor / n);
    for (let k = 0; k < n; k++) {
      const member = members[(dayIndex + k) % members.length]!;
      const startedAt = atHour(day, 8, 30 + k * 20 + rng.int(0, 25));
      const endedAt = new Date(startedAt.getTime() + hoursEach * HOUR_MS);
      const tokensIn = Math.round(hoursEach * (member.agent.modelKey === "opus" ? 120_000 : member.agent.modelKey === "haiku" ? 400_000 : 220_000) * rng.range(0.8, 1.2));
      const tokensOut = Math.round(tokensIn * rng.range(0.08, 0.16));
      const id = rng.uuid();
      sessionRows.push({
        id,
        businessId,
        agentId: member.agent.id,
        versionId: member.versionId,
        taskId: null,
        workflowId: `session:${id}`,
        modelKey: member.agent.modelKey,
        startedAt,
        endedAt,
        tokensIn,
        tokensOut,
        costMinor: spendEach,
        currency: opts.currency,
        outcome: rng.bool(0.93) ? "completed" : "stopped",
        recordingRef: null,
      });
      const mk = monthKey(startedAt);
      agentSpendByMonth.set(mk, (agentSpendByMonth.get(mk) ?? 0) + spendEach);
      if (startedAt.getTime() >= ctx.today.getTime() - 30 * DAY_MS) {
        recentSessions.push({ id, agentId: member.agent.id, modelKey: member.agent.modelKey, tokensIn, tokensOut, costMinor: spendEach, occurredAt: endedAt });
      }
    }
  }
  await bulkInsert(db, agentSessions, sessionRows);
  log(`inserted ${sessionRows.length} agent sessions`);

  // --- channel metrics per day -----------------------------------------------------------------------------------------
  const firstChannelByVisitor = new Map<string, ChannelKey | null>();
  for (const t of data.touches) {
    if (t.visitorId && !firstChannelByVisitor.has(t.visitorId)) firstChannelByVisitor.set(t.visitorId, t.channelKey);
  }
  type DayMetric = { spend: number; leads: number; signups: number; activations: number; customers: number; impressions: number };
  const metric = new Map<string, DayMetric>();
  const metricKey = (day: string, channel: ChannelKey) => `${day}|${channel}`;
  const bump = (day: string, channel: ChannelKey | null, patch: Partial<DayMetric>) => {
    if (!channel) return;
    const key = metricKey(day, channel);
    const cur = metric.get(key) ?? { spend: 0, leads: 0, signups: 0, activations: 0, customers: 0, impressions: 0 };
    for (const [k, v] of Object.entries(patch)) cur[k as keyof DayMetric] += v ?? 0;
    metric.set(key, cur);
  };
  const revenueByMonth = new Map<string, number>();
  for (const c of data.conversions) {
    const customer = c.entityId ? customersByEntityId.get(c.entityId) : undefined;
    const channel = customer ? (firstChannelByVisitor.get(customer.visitorId) ?? null) : null;
    const day = c.occurredAt.slice(0, 10);
    if (c.kind === "signup") bump(day, channel, { signups: 1, leads: channel === "lead_generation" || channel === "content" || channel === "events" ? 2 : 0 });
    else if (c.kind === "activation") bump(day, channel, { activations: 1 });
    else {
      bump(day, channel, { customers: 1 });
      const mk = c.occurredAt.slice(0, 7);
      revenueByMonth.set(mk, (revenueByMonth.get(mk) ?? 0) + c.amountMinor);
    }
  }
  const spendShare = opts.channels.filter((c) => c.enabled && !c.kitMode && c.channelKey !== "paid_ads").map((c) => c.channelKey);
  const paidEnabled = channelByKey.get("paid_ads")?.enabled ?? false;
  const adSpendByMonth = new Map<string, number>();
  for (const row of data.daily) {
    if (row.departmentId || row.spendMinor <= 0) continue;
    const paidPart = paidEnabled ? Math.round(row.spendMinor * (spendShare.length ? 0.65 : 1)) : 0;
    if (paidPart > 0) bump(row.day, "paid_ads", { spend: paidPart, impressions: paidPart * 9 });
    const rest = row.spendMinor - paidPart;
    if (rest > 0 && spendShare.length) {
      const each = Math.round(rest / spendShare.length);
      for (const k of spendShare) bump(row.day, k, { spend: each, impressions: each * 3 });
    }
    const mk = row.day.slice(0, 7);
    adSpendByMonth.set(mk, (adSpendByMonth.get(mk) ?? 0) + row.spendMinor);
  }
  const metricRows: NewChannelMetric[] = [];
  for (const [key, m] of metric) {
    const [day, channelKey] = key.split("|") as [string, ChannelKey];
    const channel = channelByKey.get(channelKey);
    if (!channel) continue;
    metricRows.push({
      id: rng.uuid(),
      businessId,
      channelId: channel.id,
      campaignId: null,
      day,
      spendMinor: m.spend,
      currency: opts.currency,
      impressions: m.impressions,
      leads: m.leads,
      signups: m.signups,
      activations: m.activations,
      customers: m.customers,
      cpaMinor: m.customers > 0 ? Math.round(m.spend / m.customers) : null,
    });
  }
  await bulkInsert(db, channelMetrics, metricRows);

  // --- summary ---------------------------------------------------------------------------------------------------------
  const last30 = ctx.today.getTime() - 30 * DAY_MS;
  const revenueLast30dMinor = payments.filter((c) => Date.parse(c.occurredAt) >= last30).reduce((s, c) => s + c.amountMinor, 0);
  const spendLast30dMinor = data.daily.filter((r) => !r.departmentId && new Date(`${r.day}T00:00:00.000Z`).getTime() >= last30).reduce((s, r) => s + r.spendMinor, 0);
  const latestPayments: LatestPayment[] = latest
    .map((c) => ({ conversion: c, customer: customersByEntityId.get(c.entityId ?? "")!, journeyId: journeyIdByConversion.get(c.id) ?? null, eventId: eventIdByConversion.get(c.id) ?? null }))
    .filter((p) => Boolean(p.customer))
    .reverse();

  return {
    data,
    customersByEntityId,
    latestPayments,
    revenueByMonth,
    agentSpendByMonth,
    adSpendByMonth,
    paidCustomers: data.series.customersByDay[data.series.customersByDay.length - 1] ?? 0,
    signups: kindCount.signup,
    activations: kindCount.activation,
    mrrMinorNow: data.series.mrrMinorByDay[data.series.mrrMinorByDay.length - 1] ?? 0,
    revenueLast30dMinor,
    spendLast30dMinor,
    counts: {
      entities: entityRows.length,
      visitors: visitorRows.length,
      touches: touchRows.length,
      conversions: conversionRows.length,
      journeys: journeyRows.length,
      milestones: milestoneRows.length,
      sessions: sessionRows.length,
      channelMetrics: metricRows.length,
      campaigns: campaignRows.length,
      events: eventRows.length,
    },
    recentSessions,
    campaignIdsByChannel,
    trophyMilestoneIds,
    channelById,
  };
}

/** Day key helper re-exported for the business modules. */
export { dayKey };
